// The model manager (mdlManager.c / mdlFile.c, the band 0x311310-0x320000) of SLUS_216.21 -- Phase 5 slice `models`:
// the model instance record (MdlModel, 1,072 bytes, kept in one list per model kind at gMdlLists 0x9571F0), its
// creation from files / memory / archives through the H_Cdvd layer and the load state machine, the RenderWare clump
// set-up (pipelines, skin types, material colours, UV animations), the four animation slots (animation sets, set-time /
// speed / end callbacks, the bone-scale hook, the look-at controls), attachments (five child models on helper frames),
// helpers, effect lists and after effects bound to helpers, the model sound record, and the destroy path.
//
// Generated by p3fes_handgen (one statement per instruction on the hg_cpu register view: frame, spills, $ra links,
// cycle charges and check points exactly as the recompiled bodies) and made readable on top -- roles, named offsets
// (models.h), callee roles, block roles; no statement moved. The pair tests (tests/game/test_models.cpp) run every
// body against its recompiled body on built model records and the stand-in heap / file layer (tests/game/stand_ins.h).
// Proposed names are in brackets (symbols/deltas/models.sym); the names in code are symbols/functions.json's.
