void sub_31FDE0(EEContext& ctx) {
    using namespace hg;
    Gpr zero{ctx, 0}, v0{ctx, 2}, v1{ctx, 3}, a0{ctx, 4}, a1{ctx, 5}, t1{ctx, 9}, sp{ctx, 29}, ra{ctx, 31};
    Fpr f0{ctx, 0}, f1{ctx, 1}, f2{ctx, 2}, f3{ctx, 3}, f4{ctx, 4}, f13{ctx, 13};
    // 0x0031fde0
    enter(ctx, 8);  // entry check point + this block's cycles
    sp = addiu(sp, -0x10);
    sd(ra, sp, 0x0);
    t1 = a1;
    jal(ctx, 0x31FDECu, gen::fn_sub_31FBD0_0031fbd0);  // [mdlCurveEvalVec3]
    lbu(v1, t1, 1);
    if (i64(v1) < 0) {
        // 0x0031fe14
        charge(ctx, 7);
        a0 = srl(v1, 1);
        v1 = v1 & 0x1;
        a0 = a0 | v1;
        mtc1(a0, f0);
        cvt_s_w(f1, f0);
        add_s(f1, f1, f1);
    } else {
        // 0x0031fe00
        charge(ctx, 5);
        mtc1(v1, f0);
        cvt_s_w(f1, f0);
    }
    // 0x0031fe30
    charge(ctx, 9);
    v1 = 0x437F0000;
    mtc1(v1, f0);
    div_s(f4, f1, f0);
    lbu(v1, t1, 2);
    if (i64(v1) < 0) {
        // 0x0031fe68
        charge(ctx, 7);
        a0 = srl(v1, 1);
        v1 = v1 & 0x1;
        a0 = a0 | v1;
        mtc1(a0, f0);
        cvt_s_w(f1, f0);
        add_s(f1, f1, f1);
    } else {
        // 0x0031fe54
        charge(ctx, 5);
        mtc1(v1, f0);
        cvt_s_w(f1, f0);
    }
    // 0x0031fe84
    charge(ctx, 9);
    v1 = 0x437F0000;
    mtc1(v1, f0);
    div_s(f3, f1, f0);
    lbu(v1, t1, 0);
    if (i64(v1) < 0) {
        // 0x0031febc
        charge(ctx, 7);
        a0 = srl(v1, 1);
        v1 = v1 & 0x1;
        a0 = a0 | v1;
        mtc1(a0, f0);
        cvt_s_w(f1, f0);
        add_s(f1, f1, f1);
    } else {
        // 0x0031fea8
        charge(ctx, 5);
        mtc1(v1, f0);
        cvt_s_w(f1, f0);
    }
    // 0x0031fed8 (the shared epilogue, written out on this path)
    charge(ctx, 25);
    v1 = 0x437F0000;
    mtc1(v1, f0);
    div_s(f0, f1, f0);
    lwc1(f1, v0, 4);
    sub_s(f0, f0, f1);
    mtc1(zero, f2);
    adda_s(f2, f1);
    madd_s(f0, f13, f0);
    swc1(f0, v0, 4);
    lwc1(f1, v0, 8);
    sub_s(f0, f4, f1);
    adda_s(f2, f1);
    madd_s(f0, f13, f0);
    swc1(f0, v0, 8);
    lwc1(f1, v0, 12);
    sub_s(f0, f3, f1);
    adda_s(f2, f1);
    madd_s(f0, f13, f0);
    swc1(f0, v0, 12);
    ld(ra, sp, 0x0);
    sp = addiu(sp, 0x10);
}

